1	package typesys
2	
3	import (
4		"fmt"
5	
6		"github.com/user/freelang-evolving-compiler/internal/ast"
7	)
8	
9	// TypeError represents a type checking error
10	type TypeError struct {
11		Message string
12		Line    int
13		Col     int
14	}
15	
16	// TypeChecker validates types in an AST
17	type TypeChecker struct {
18		env    *TypeEnv
19		errors []TypeError
20	}
21	
22	// NewTypeChecker creates a new type checker
23	func NewTypeChecker() *TypeChecker {
24		return &TypeChecker{
25			env:    NewTypeEnv(),
26			errors: []TypeError{},
27		}
28	}
29	
30	// Check walks the AST and validates types, returning any errors found
31	func (tc *TypeChecker) Check(root *ast.Node) []TypeError {
32		if root != nil {
33			tc.checkNode(root)
34		}
35		return tc.errors
36	}
37	
38	// checkNode recursively checks a node and returns its inferred type
39	func (tc *TypeChecker) checkNode(n *ast.Node) TypeInfo {
40		if n == nil {
41			return UnknownType
42		}
43	
44		switch n.Kind {
45		case ast.NodeProgram:
46			// Check all top-level statements
47			for _, child := range n.Children {
48				tc.checkNode(child)
49			}
50			return UnitType
51	
52		case ast.NodeStructDecl:
53			return tc.checkStructDecl(n)
54	
55		case ast.NodeLetDecl:
56			return tc.checkLetDecl(n)
57	
58		case ast.NodeFnDecl:
59			return tc.checkFnDecl(n)
60	
61		case ast.NodeBlockStmt:
62			tc.env.EnterScope()
63			for _, child := range n.Children {
64				tc.checkNode(child)
65			}
66			tc.env.ExitScope()
67			return UnitType
68	
69		case ast.NodeIfStmt:
70			if len(n.Children) > 0 {
71				condType := tc.checkNode(n.Children[0])
72				if condType.Kind != TypeBool && condType.Kind != TypeUnknown {
73					tc.addError(fmt.Sprintf("if condition must be bool, got %v", condType), n.Line, n.Col)
74				}
75			}
76			if len(n.Children) > 1 {
77				tc.checkNode(n.Children[1])
78			}
79			return UnitType
80	
81		case ast.NodeReturn:
82			if len(n.Children) > 0 {
83				return tc.checkNode(n.Children[0])
84			}
85			return UnitType
86	
87		case ast.NodeBinaryExpr:
88			return tc.checkBinaryExpr(n)
89	
90		case ast.NodeFieldAccess:
91			return tc.checkFieldAccess(n)
92	
93		case ast.NodeCallExpr:
94			return tc.checkCallExpr(n)
95	
96		case ast.NodeIdent:
97			if t, found := tc.env.Lookup(n.Value); found {
98				return t
99			}
100			tc.addError(fmt.Sprintf("unknown variable '%s'", n.Value), n.Line, n.Col)
101			return UnknownType
102	
103		case ast.NodeIntLit:
104			return IntType
105	
106		case ast.NodeForStmt:
107			// Register iterator variable as int (simplified)
108			if len(n.Children) > 0 && n.Children[0].Kind == ast.NodeIdent {
109				tc.env.Define(n.Children[0].Value, IntType)
110			}
111			if len(n.Children) > 2 {
112				tc.checkNode(n.Children[2]) // body
113			}
114			return UnitType
115	
116		default:
117			return UnknownType
118		}
119	}
120	
121	// checkStructDecl registers a struct definition
122	func (tc *TypeChecker) checkStructDecl(n *ast.Node) TypeInfo {
123		structName := n.Value
124		def := StructDef{
125			Name:   structName,
126			Fields: make(map[string]TypeInfo),
127		}
128	
129		// Extract field types from children
130		for _, child := range n.Children {
131			if child.Kind == ast.NodeFieldDecl {
132				fieldName := child.Value
133				// Field type is in TypeAnnotation or Children[0].Value
134				fieldType := UnknownType
135				if child.TypeAnnotation != "" {
136					fieldType = TypeFromAnnotation(child.TypeAnnotation)
137				} else if len(child.Children) > 0 {
138					// Type is in Children[0].Value
139					fieldType = TypeFromAnnotation(child.Children[0].Value)
140				}
141				def.Fields[fieldName] = fieldType
142			}
143		}
144	
145		tc.env.RegisterStruct(structName, def)
146		return UnitType
147	}
148	
149	// checkLetDecl validates variable declaration and registration
150	func (tc *TypeChecker) checkLetDecl(n *ast.Node) TypeInfo {
151		if len(n.Children) < 2 {
152			return UnknownType
153		}
154	
155		nameNode := n.Children[0]
156		valueNode := n.Children[1]
157	
158		// Determine the type of the variable
159		var varType TypeInfo
160	
161		// If there's a type annotation, use it
162		if nameNode.TypeAnnotation != "" {
163			varType = TypeFromAnnotation(nameNode.TypeAnnotation)
164		} else {
165			// Infer from the value expression
166			varType = tc.checkNode(valueNode)
167		}
168	
169		// Check value type matches declared type
170		valueType := tc.checkNode(valueNode)
171		if nameNode.TypeAnnotation != "" && valueType.Kind != TypeUnknown {
172			if !varType.Equals(valueType) {
173				tc.addError(
174					fmt.Sprintf("type mismatch: expected %v, got %v", varType, valueType),
175					n.Line, n.Col,
176				)
177			}
178		}
179	
180		// Register the variable
181		tc.env.Define(nameNode.Value, varType)
182		return UnitType
183	}
184	
185	// checkFnDecl validates function declaration
186	func (tc *TypeChecker) checkFnDecl(n *ast.Node) TypeInfo {
187		// Register function parameters
188		tc.env.EnterScope()
189		for _, child := range n.Children {
190			if child.Kind == ast.NodeIdent {
191				// This is a parameter
192				paramType := UnknownType
193				if child.TypeAnnotation != "" {
194					paramType = TypeFromAnnotation(child.TypeAnnotation)
195				}
196				tc.env.Define(child.Value, paramType)
197			}
198		}
199	
200		// Check function body
201		for _, child := range n.Children {
202			if child.Kind == ast.NodeBlockStmt {
203				tc.checkNode(child)
204				break
205			}
206		}
207	
208		tc.env.ExitScope()
209	
210		// Register function type (simplified for Phase 1)
211		return UnitType
212	}
213	
214	// checkBinaryExpr validates binary expression type correctness
215	func (tc *TypeChecker) checkBinaryExpr(n *ast.Node) TypeInfo {
216		if len(n.Children) < 2 {
217			return UnknownType
218		}
219	
220		leftType := tc.checkNode(n.Children[0])
221		rightType := tc.checkNode(n.Children[1])
222	
223		// For now, both operands must be int for arithmetic
224		op := n.Value
225		if op == "+" || op == "-" || op == "*" || op == "/" {
226			if leftType.Kind != TypeInt && leftType.Kind != TypeUnknown {
227				tc.addError(
228					fmt.Sprintf("left operand of %s must be int, got %v", op, leftType),
229					n.Line, n.Col,
230				)
231			}
232			if rightType.Kind != TypeInt && rightType.Kind != TypeUnknown {
233				tc.addError(
234					fmt.Sprintf("right operand of %s must be int, got %v", op, rightType),
235					n.Line, n.Col,
236				)
237			}
238			return IntType
239		}
240	
241		// Comparison operators return bool
242		if op == "==" || op == "!=" || op == "<" || op == ">" || op == "<=" || op == ">=" {
243			if !leftType.Equals(rightType) && leftType.Kind != TypeUnknown && rightType.Kind != TypeUnknown {
244				tc.addError(
245					fmt.Sprintf("type mismatch in %s: %v vs %v", op, leftType, rightType),
246					n.Line, n.Col,
247				)
248			}
249			return BoolType
250		}
251	
252		return UnknownType
253	}
254	
255	// checkFieldAccess validates field access and returns field type
256	func (tc *TypeChecker) checkFieldAccess(n *ast.Node) TypeInfo {
257		if len(n.Children) == 0 {
258			return UnknownType
259		}
260	
261		// Get the object type
262		objType := tc.checkNode(n.Children[0])
263		fieldName := n.Value
264	
265		// Look up struct definition
266		if objType.Kind == TypeStruct {
267			if structDef, found := tc.env.LookupStruct(objType.StructName); found {
268				if fieldType, fieldExists := structDef.Fields[fieldName]; fieldExists {
269					return fieldType
270				}
271				tc.addError(
272					fmt.Sprintf("unknown field '%s' on struct '%s'", fieldName, objType.StructName),
273					n.Line, n.Col,
274				)
275				return UnknownType
276			}
277			tc.addError(fmt.Sprintf("unknown struct '%s'", objType.StructName), n.Line, n.Col)
278			return UnknownType
279		}
280	
281		// Object is not a struct
282		if objType.Kind != TypeUnknown {
283			tc.addError(
284				fmt.Sprintf("cannot access field '%s' on non-struct type %v", fieldName, objType),
285				n.Line, n.Col,
286			)
287		}
288		return UnknownType
289	}
290	
291	// checkCallExpr validates function call (simplified for Phase 1)
292	func (tc *TypeChecker) checkCallExpr(n *ast.Node) TypeInfo {
293		// Phase 1: Just validate that the function exists
294		name := n.Value
295		if _, found := tc.env.Lookup(name); !found && name != "print" && name != "len" && name != "str" {
296			tc.addError(fmt.Sprintf("unknown function '%s'", name), n.Line, n.Col)
297		}
298		return UnknownType
299	}
300	
301	// addError records a type error
302	func (tc *TypeChecker) addError(msg string, line, col int) {
303		tc.errors = append(tc.errors, TypeError{
304			Message: msg,
305			Line:    line,
306			Col:     col,
307		})
308	}
