3	// Scope represents a single block's variable type environment
4	type Scope struct {
5		vars   map[string]TypeInfo
6		parent *Scope
7	}
8	
9	func newScope(parent *Scope) *Scope {
10		return &Scope{
11			vars:   make(map[string]TypeInfo),
12			parent: parent,
13		}
14	}
15	
16	// Define adds a variable to this scope
17	func (s *Scope) define(name string, t TypeInfo) {
18		s.vars[name] = t
19	}
20	
21	// Lookup searches for a variable type in this scope and parent scopes
22	func (s *Scope) lookup(name string) (TypeInfo, bool) {
23		if t, exists := s.vars[name]; exists {
24			return t, true
25		}
26		if s.parent != nil {
27			return s.parent.lookup(name)
28		}
29		return UnknownType, false
30	}
31	
32	// StructDef represents a struct definition
33	type StructDef struct {
34		Name   string
35		Fields map[string]TypeInfo // fieldname -> type
36	}
37	
38	// TypeEnv is the complete type environment
39	type TypeEnv struct {
40		current *Scope
41		structs map[string]StructDef
42	}
43	
44	// NewTypeEnv creates a new type environment
45	func NewTypeEnv() *TypeEnv {
46		global := newScope(nil)
47		return &TypeEnv{
48			current: global,
49			structs: make(map[string]StructDef),
50		}
51	}
52	
53	// EnterScope creates a new nested scope
54	func (e *TypeEnv) EnterScope() {
55		e.current = newScope(e.current)
56	}
57	
58	// ExitScope pops to parent scope
59	func (e *TypeEnv) ExitScope() {
60		if e.current.parent != nil {
61			e.current = e.current.parent
62		}
63	}
64	
65	// Define adds a variable to current scope
66	func (e *TypeEnv) Define(name string, t TypeInfo) {
67		e.current.define(name, t)
68	}
69	
70	// Lookup searches for a variable in current scope and parents
71	func (e *TypeEnv) Lookup(name string) (TypeInfo, bool) {
72		return e.current.lookup(name)
73	}
74	
75	// RegisterStruct adds a struct definition
76	func (e *TypeEnv) RegisterStruct(name string, def StructDef) {
77		e.structs[name] = def
78	}
79	
80	// LookupStruct finds a struct definition
81	func (e *TypeEnv) LookupStruct(name string) (StructDef, bool) {
82		s, exists := e.structs[name]
83		return s, exists
84	}
